package vn.vinhkhang.warehouse;
import org.junit.jupiter.api.Test;import java.util.*;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;
class CommercialPrintTest {
 Map<String,Object> item(String type,String code,String description,String price,int requested){var m=new HashMap<String,Object>();m.put("VEHICLE_TYPE",type);m.put("ITEM_CODE",code);m.put("DESCRIPTION",description);m.put("UNIT_PRICE",price==null?null:new BigDecimal(price));m.put("REQUESTED_QUANTITY",requested);m.put("FRAME_NUMBER","FRAME");m.put("MOTOR_NUMBER","MOTOR");return m;}
 Map<String,Object> shipment(){return Map.of("CODE","X-TEST","SHIPMENT_DATE","2026-10-05","CUSTOMER","Khách");}
 @Test void twentyCommercialVehiclesPrintOneRowWithTotals(){var lines=new ArrayList<Map<String,Object>>();for(int i=0;i<20;i++)lines.add(item("COMMERCIAL","LX800","Y-BIKES800 - Đen Bạc","10000000",1));var grouped=SalesShipments.printLines(lines);assertEquals(1,grouped.size());assertEquals(20,grouped.getFirst().quantity());assertEquals(20,grouped.getFirst().requested());var html=SalesShipments.html(shipment(),lines);assertTrue(html.contains("<td>Chiếc</td><td>20</td><td>20</td></tr>"));assertTrue(html.contains("Cộng</td><td>20</td><td>20</td>"));assertFalse(html.contains("Số khung:"));assertEquals(20,lines.size());assertFalse(html.contains("10.000.000"));assertFalse(html.contains("200.000.000"));}
 @Test void separateModelsColorsPricesAndRegisteredVehicles(){var lines=List.of(item("COMMERCIAL","M1","Xe - Đen","10.00",2),item("COMMERCIAL","M1","Xe - Đen","10.0",3),item("COMMERCIAL","M1","Xe - Đỏ","10",1),item("COMMERCIAL","M2","Xe - Đen","10",1),item("COMMERCIAL","M1","Xe - Đen","20",1),item("COMMERCIAL","M1","Xe - Đen",null,1),item("REGISTERED","M1","Xe - Đen","10",1),item("REGISTERED","M1","Xe - Đen","10",1));var grouped=SalesShipments.printLines(lines);assertEquals(7,grouped.size());assertEquals(2,grouped.getFirst().quantity());assertEquals(5,grouped.getFirst().requested());String html=SalesShipments.html(shipment(),lines);assertTrue(html.contains("Cộng</td><td>11</td><td>8</td>"));assertTrue(html.contains("Số khung: FRAME"));assertFalse(html.contains("Đơn giá"));assertFalse(html.contains("Thành tiền"));assertEquals(5,SalesShipments.noPriceLines(lines).size());}
 @Test void missingPricesStayBlankAndDescriptionsAreEscaped(){var lines=List.of(item("COMMERCIAL","M<1","Xe <script> - Đen",null,1),item("COMMERCIAL","M<1","Xe <script> - Đen",null,1));String html=SalesShipments.html(shipment(),lines);assertTrue(html.contains("<td>2</td><td>2</td></tr>"));assertTrue(html.contains("M&lt;1"));assertTrue(html.contains("Xe &lt;script&gt;"));assertFalse(html.contains("Xe <script>"));}
}
